1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionCursor} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // list_sessions is answered off the lock: a history request must not queue behind a streaming turn.
57	    if (isListSessionsFrame(rawMessage)) {
58	      return wsErrorHandler(ws, async () => answerListSessions(ws, session, sessionStore, validation));
59	    }
60	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
61	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
62	  };
63	}
64	
65	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
66	async function answerInTurn(
67	  ws: WebSocket,
68	  session: ChatSession,
69	  orchestrator: ChatOrchestrator,
70	  validation: ValidationResult,
71	  signal: AbortSignal | undefined
72	): Promise<void> {
73	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
74	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
75	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
76	    return;
77	  }
78	  const startedAt = Date.now();
79	  try {
80	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
81	  } finally {
82	    endTurn(ws, session, signal, startedAt);
83	  }
84	}
85	
86	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
87	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
88	  if (signal?.aborted) {
89	    log.info('message', 'turn abandoned: its socket closed', {
90	      sessionId: session.sessionId,
91	      elapsedMs: Date.now() - startedAt,
92	    });
93	    return;
94	  }
95	  sendStreamEnd(ws);
96	}
97	
98	async function answerUserMessage(
99	  ws: WebSocket,
100	  session: ChatSession,
101	  orchestrator: ChatOrchestrator,
102	  validation: ValidationResult,
103	  signal: AbortSignal | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  answerFrame(ws, validation);
108	}
109	
110	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
111	  if (!validation.valid) {
112	    log.warn('message', 'validation failed', {error: validation.error});
113	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
114	    return;
115	  }
116	
117	  const message = validation.data;
118	  if (message.type === 'ping') handlePing(ws, message.timestamp);
119	}
120	
121	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
122	function isUserMessageFrame(rawMessage: unknown): boolean {
123	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
124	}
125	
126	function isListSessionsFrame(rawMessage: unknown): boolean {
127	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_sessions';
128	}
129	
130	async function answerListSessions(
131	  ws: WebSocket,
132	  session: ChatSession,
133	  sessionStore: SessionStore | undefined,
134	  validation: ReturnType<typeof validateMessage>
135	): Promise<void> {
136	  if (!validation.valid) {
137	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
138	    return;
139	  }
140	  const message = validation.data;
141	  if (message.type !== 'list_sessions') return;
142	  await handleListSessions(ws, session, sessionStore, message.limit, message.before);
143	}
144	
145	async function handleListSessions(
146	  ws: WebSocket,
147	  session: ChatSession,
148	  sessionStore: SessionStore | undefined,
149	  limit: number | undefined,
150	  before: SessionCursor | undefined
151	): Promise<void> {
152	  if (!sessionStore?.listFor) {
153	    sendSessionList(ws, []);
154	    return;
155	  }
156	  try {
157	    const summaries = await sessionStore.listFor(session.userId, {limit, before});
158	    const sessions: SessionSummaryFrame[] = summaries.map(s => ({
159	      sessionId: s.sessionId,
160	      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
161	      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
162	      entryCount: s.entryCount,
163	    }));
164	    sendSessionList(ws, sessions);
165	  } catch (error) {
166	    const msg = error instanceof Error ? error.message : 'Unknown error';
167	    log.error('ws', 'listFor failed', {userId: session.userId, error: msg});
168	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
169	  }
170	}
171	
172	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
173	  try {
174	    await action();
175	  } catch (error) {
176	    const message = error instanceof Error ? error.message : 'Unknown error';
177	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
178	    log.error('message', 'handling error', {error: message, code});
179	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
180	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
181	      return;
182	    }
183	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
184	  }
185	}
186	
187	async function handleUserMessage(
188	  ws: WebSocket,
189	  session: ChatSession,
190	  orchestrator: ChatOrchestrator,
191	  content: string,
192	  signal: AbortSignal | undefined
193	): Promise<void> {
194	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
195	
196	  const userEntry = createUserEntry(content);
197	  const userIndex = appendEntry(session, userEntry);
198	  sendUpsert(ws, userIndex, userEntry);
199	
200	  const parser = new ThinkingTagParser();
201	  const state: StreamState = {
202	    thinkingIndex: null,
203	    assistantIndex: null,
204	    suppressOutput: false,
205	    sentAssistantIndices: [],
206	  };
207	
208	  let textChunkCount = 0;
209	
210	  try {
211	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
212	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
213	      if (signal?.aborted) break;
214	      textChunkCount = logChunk(chunk, textChunkCount);
215	      processChunk(ws, session, state, parser, chunk);
216	    }
217	  } finally {
218	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
219	    flushHeldText(ws, session, state, parser);
220	    closeCutOff(ws, session, state, 'thinkingIndex');
221	    closeCutOff(ws, session, state, 'assistantIndex');
222	  }
223	
224	  if (textChunkCount > 0) {
225	    log.debug('stream', `received ${textChunkCount} text chunks`);
226	  }
227	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
228	}
229	
230	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
231	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
232	  if (chunk.type === 'text') return textChunkCount + 1;
233	
234	  if (textChunkCount > 0) {
235	    log.debug('stream', `received ${textChunkCount} text chunks`);
236	  }
237	
238	  if (chunk.type === 'tool_result') {
239	    log.debug('stream', 'tool_result chunk', {
240	      messageCount: chunk.clientMessages.length,
241	      types: chunk.clientMessages.map(m => m.type),
242	    });
243	    return 0;
244	  }
245	
246	  log.debug('stream', 'chunk', {type: chunk.type});
247	  return 0;
248	}
249	
250	function processChunk(
251	  ws: WebSocket,
252	  session: ChatSession,
253	  state: StreamState,
254	  parser: ThinkingTagParser,
255	  chunk: MessageChunk
256	): void {
257	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
258	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
259	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
260	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
