  const {limit, before} = message;

  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1) {
      return {valid: false, error: 'limit must be a positive integer'};
    }
  }

  if (before !== undefined) {
    if (typeof before !== 'object' || before === null) {
      return {valid: false, error: 'before must be an object with sessionId and updatedAt'};
    }
    const cursor = before as Record<string, unknown>;
    if (
      typeof cursor.sessionId !== 'string' ||
      cursor.sessionId.length < 1 ||
      cursor.sessionId.length > MAX_CURSOR_SESSION_ID
    ) {
      return {valid: false, error: 'before.sessionId must be a string between 1 and 128 characters'};
    }
    if (typeof cursor.updatedAt !== 'string' && typeof cursor.updatedAt !== 'number') {
      return {valid: false, error: 'before.updatedAt must be a string or number'};
    }
    if (typeof cursor.updatedAt === 'string' && isNaN(Date.parse(cursor.updatedAt))) {
      return {valid: false, error: 'before.updatedAt must be a valid date string'};
    }
  }

  const data: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) data.limit = limit as number;
  if (before !== undefined) data.before = before as SessionCursor;

  return {valid: true, data};
}

